async function hold(){held.value.push({id:newId(),name:holdName.value.trim()||`Order ${held.value.length+1}`,items:JSON.parse(JSON.stringify(cart.value)),customerId:customerId.value,customerEmail:customerEmail.value,customerName:customerName.value,saleId:saleId.value,discount:discount.value,overrideReason:overrideReason.value,voucherCode:voucherCode.value,total:totals.value.total,date:new Date().toISOString()});cart.value=[];customerId.value='';customerEmail.value='';customerName.value='';saleId.value=newId();discount.value=0;overrideReason.value='';voucherCode.value='';pricingQuote.value=null;modal.value='';await persist();Store.notify('Order held on this device.');}
async function restore(index){const order=held.value[index];if(cart.value.length)held.value.push({id:newId(),name:'Previous cart',items:JSON.parse(JSON.stringify(cart.value)),customerId:customerId.value,customerEmail:customerEmail.value,customerName:customerName.value,saleId:saleId.value,discount:discount.value,overrideReason:overrideReason.value,voucherCode:voucherCode.value,total:totals.value.total,date:new Date().toISOString()});cart.value=order.items;customerId.value=order.customerId;await Promise.resolve();customerEmail.value=order.customerEmail||selectedCustomer.value?.email||'';customerName.value=order.customerName||selectedCustomer.value?.name||'';saleId.value=order.saleId;discount.value=Number(order.discount||0);overrideReason.value=order.overrideReason||'';voucherCode.value=order.voucherCode||'';pricingQuote.value=null;held.value.splice(index,1);modal.value='';}
function scan(){const code=search.value.trim().toUpperCase();if(!code)return;const matches=[];for(const p of products.value){if([p.sku,p.barcode,p.code].some(v=>v&&v.toUpperCase()===code))matches.push([p,null]);for(const v of p.variants)if([v.sku,v.barcode].some(c=>c&&c.toUpperCase()===code))matches.push([p,v]);}if(matches.length===1){add(...matches[0]);search.value='';}else Store.notify(matches.length?'Multiple items use this code. Choose the correct item.':'No exact SKU or barcode match.','error');}
function shortcut(e){if(modal.value||receipt.value)return;if(e.key==='F2'){e.preventDefault();productSearch.value?.focus();}if(e.key==='F8'){e.preventDefault();openPayment();}}
function viewCart(){cartPanel.value?.scrollIntoView({behavior:Store.state.preferences.reduceMotion?'instant':'smooth',block:'start'});}
async function loadCustomerOrder(id){
  if(!id||requestLoading.value||!Store.state.online)return;
  requestLoading.value=true;error.value='';
  try{
    const orderPath=`/companies/${encodeURIComponent(company.value.id)}/customer-orders/${encodeURIComponent(id)}`;
    const [detail,paymentEvidence]=await Promise.all([api(orderPath),api(`${orderPath}/online-payment`)]);
    const onlinePayment=paymentEvidence.onlinePayment||null;
    const items=customerOrderCart(detail.order);
    if(!isTenderableCustomerOrder(detail.order,onlinePayment)){
      if(blocksCounterPayment(onlinePayment))throw new Error(`${customerOrderOnlinePaymentLabel(onlinePayment)}. Do not collect payment again. Review the provider evidence in Sales Orders.`);
      throw new Error('This request is not ready for counter payment. Do not collect payment. Review it in Sales Orders.');
    }
    if(!validCustomerOrderCart(items))throw new Error('This request cannot be loaded safely. Review its product details in Sales Orders.');
    incomingRequest.value={...detail,onlinePayment,items};modal.value='customer-order';
  }catch(caught){error.value=caught.message||'The customer order could not be loaded.';Store.notify(error.value,'error');}
  finally{requestLoading.value=false;}
}
async function applyCustomerOrder(){
  const detail=incomingRequest.value;if(!detail)return;
  if(cart.value.length)held.value.push({id:newId(),name:'Previous cart',items:JSON.parse(JSON.stringify(cart.value)),customerId:customerId.value,customerEmail:customerEmail.value,customerName:customerName.value,saleId:saleId.value,discount:discount.value,overrideReason:overrideReason.value,voucherCode:voucherCode.value,total:totals.value.total,date:new Date().toISOString()});
  const customer=customerOrderCustomer(detail.order);
  cart.value=detail.items.map(safeDraft);customerId.value=customer.id;await Promise.resolve();customerEmail.value=customer.email;customerName.value=customer.name;saleId.value=newId();discount.value=0;overrideReason.value='';voucherCode.value='';pricingQuote.value=null;sourceRequest.value={id:detail.order.id,code:detail.order.code||detail.order.orderCode||detail.order.number,version:detail.order.version,status:detail.order.status,currency:detail.order.currency||'',serviceMode:detail.order.serviceMode||'pickup',deliveryZoneName:detail.order.delivery?.zoneName||'',pricingSnapshotId:detail.order.checkoutCart?.pricingSnapshotId||'',discounts:detail.order.checkoutCart?.discounts||[],totals:detail.order.checkoutCart?.totals||null};tenderRetry.value=null;incomingRequest.value=null;modal.value='';
  const query={...route.query};delete query.customerOrder;await router.replace({query});await persist();Store.notify(detail.order.serviceMode==='delivery'?'Delivery request loaded. Record the full accepted total once.':'Customer request loaded. Collect payment once at the counter.');
}
</script>
  <template><div class="ed-page ed-pos-page"><header class="ed-page-head"><div><div class="ed-eyebrow">POINT OF SALE / {{ company.name }}</div><h1>Make someone's day.</h1><p>A good checkout should feel effortless.</p></div><div class="ed-actions"><router-link to="/orders" class="ed-btn"><Icon name="clock" />Pending orders<span v-if="pendingOrderCount+pendingRequestCount" class="ed-pill warning">{{ pendingOrderCount+pendingRequestCount }}</span></router-link><button class="ed-btn" @click="modal='held'"><Icon name="clock" />Held carts<span v-if="held.length" class="ed-pill">{{ held.length }}</span></button><button class="ed-btn" @click="modal='recent'"><Icon name="receipt" />Recent sales</button></div></header>
