v-if="pricingLine(i)?.savings">{{ money(pricingLine(i).gross,currency) }}</s><strong>{{ money(pricingLine(i)?.net??lineTotal(item),currency) }}</strong></span></div></div><div v-for="reward in automaticRewardLines" :key="`reward-${reward.lineNo}`" class="ed-cart-item mf-pos-reward"><div><span class="mf-pos-reward-label">Automatic reward</span><strong>{{ reward.description }}</strong><small>{{ reward.quantity }} × {{ money(reward.unitPrice,currency) }} · Added by campaign</small></div><span class="mf-pos-line-price"><s>{{ money(reward.gross,currency) }}</s><strong>{{ money(reward.net,currency) }}</strong></span></div><div v-if="!cart.length" class="ed-empty" style="border:0"><Icon name="bag" /><h3>A fresh order.</h3><p>Choose an item to get started.</p></div><div style="padding-top:12px"><section v-if="!sourceRequest" class="mf-pos-promotions"><header><div><span class="ed-eyebrow">PROMOTIONS</span><strong>{{ appliedVoucher?'Code accepted':voucherCode?'Code entered':'Automatic offers are checked' }}</strong></div><button class="ed-btn compact" type="button" :disabled="busy" @click="openPromotions"><Icon name="percent"/>Browse</button></header><label class="ed-field"><span>Scan or enter reusable code</span><div class="mf-pos-code-input"><input v-model="voucherCode" maxlength="32" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="STUDENT or STAFF" :disabled="busy" @change="normalizeVoucherInput" @keydown.enter.prevent="normalizeVoucherInput"><button v-if="voucherCode" class="ed-icon-button" type="button" aria-label="Remove promotion code" @click="clearPromotionCode"><Icon name="close"/></button></div><small>Press Enter after a scanner or keyboard entry. The server confirms eligibility and savings.</small></label></section><label v-if="discountLimit>0||discount>0" class="ed-field"><span>Discretionary discount (%)</span><input v-model.number="discount" type="number" min="0" :max="discountLimit" step="0.01" :disabled="busy||!!sourceRequest"><small>{{ sourceRequest?'Accepted quote locked':'Separate from automatic promotions · account limit: '+discountLimit+'%' }}</small></label><label v-if="reasonRequired" class="ed-field"><span>Manager override reason *</span><input v-model.trim="overrideReason" maxlength="500" :disabled="busy||!!sourceRequest" required placeholder="Why this discount is approved"></label><p v-if="pricingBusy" class="mf-pos-pricing-state">Checking automatic offers and codes…</p><p v-else-if="pricingError" class="mf-pos-pricing-state error">{{ pricingError }}</p><div class="ed-summary"><span>Subtotal before discounts</span><span>{{ money(totals.subtotal,currency) }}</span></div><div v-for="offer in quoteDiscounts" :key="offer.promotionId||offer.name" class="ed-summary mf-pos-offer"><span><span>{{ offer.name }}</span><small>{{ promotionCatalog.find(row=>row.promotionId===offer.promotionId)?.campaignName }}</small><em>{{ offer.voucherApplied?'Code':'Automatic' }}</em></span><span>−{{ money(offer.amount,currency) }}</span></div><div v-if="totals.manualDiscountAmount" class="ed-summary"><span>Discretionary discount {{ discount }}%</span><span>−{{ money(totals.manualDiscountAmount,currency) }}</span></div><div v-else-if="totals.discountAmount&&!quoteDiscounts.length" class="ed-summary"><span>Discount {{ discount }}%</span><span>−{{ money(totals.discountAmount,currency) }}</span></div><div v-if="totals.discountAmount" class="mf-pos-discount-impact"><div><span>Before</span><strong>{{ money(totals.subtotal,currency) }}</strong></div><div><span>After discounts</span><strong>{{ money(discountedSubtotal,currency) }}</strong></div><div><span>Customer saves</span><strong>−{{ money(totals.discountAmount,currency) }}</strong></div></div><div class="ed-summary"><span>Tax {{ totals.taxRate||0 }}%</span><span>{{ money(totals.tax,currency) }}</span></div><div v-if="totals.deliveryFee!==undefined" class="ed-summary"><span>Delivery fee</span><span>{{ money(totals.deliveryFee,currency) }}</span></div><div class=