<Modal v-if="modal==='variant'" :title="variantProduct.name" @close="modal=''"><p class="ed-muted" style="margin-bottom:20px">Choose an option for this product.</p><div class="ed-form-grid"><button v-for="v in variantProduct.variants" :key="v.id" class="ed-btn ed-variant-choice" :disabled="limitsSaleQuantity(variantProduct,v)&&available(variantProduct,v)-quantityInCart(variantProduct,v)<=0" @click="add(variantProduct,v)"><strong>{{ v.name }}</strong><small style="display:block">{{ money(v.price,currency) }}<span v-if="limitsSaleQuantity(variantProduct,v)"> · {{ Math.max(0,available(variantProduct,v)-quantityInCart(variantProduct,v)) }} available</span></small></button></div></Modal>
<Modal v-if="modal==='payment'" title="Complete the order" :busy="busy" @close="closePayment"><div v-if="sourceRequest" class="ed-notice warning"><Icon name="cloud"/><div><strong>Online request {{ sourceRequest.code }}</strong>{{ tenderRetry?'Payment may already be recorded. Retry confirmation without collecting again.':'This accepted quote will be linked to one paid sale.' }}</div></div><div v-else-if="pricingQuote?.pricingSnapshotId" class="ed-notice" :class="pricingTender.ready?'success':'error'"><Icon :name="pricingTender.ready?'clock':'alert'"/><div><strong>{{ pricingTender.ready?`Price held · ${pricingHoldClock}`:'Price hold paused' }}</strong>{{ pricingTender.ready?'Checkout pauses with one minute remaining. Collect and confirm payment before then.':'Do not collect or confirm payment. Refresh the price and review the total first.' }}<button v-if="!pricingTender.ready" type="button" class="ed-btn small" :disabled="pricingBusy" @click="refreshPaymentPricing">{{ pricingBusy?'Refreshing…':'Refresh price' }}</button></div></div><div class="ed-payment-total"><div class="ed-eyebrow">AMOUNT TO COLLECT</div><strong>{{ money(totals.total,currency) }}</strong></div><div class="ed-payment-methods"><button v-for="m in ['Cash','QR Pay','Card']" :key="m" :class="{active:method===m}" :disabled="busy||!!tenderRetry||!pricingTenderReady" @click="method=m;confirmed=false;error=''">{{ m }}</button></div><template v-if="method==='Cash'"><label class="ed-field"><span>Cash received ({{ currency }})</span><input v-model="received" type="number" inputmode="decimal" step="0.01" min="0" placeholder="0.00" :disabled="busy||!!tenderRetry||!pricingTenderReady"></label><div class="ed-actions" style="margin-top:12px"><button v-for="amount in [totals.total,50,100]" :key="amount" class="ed-btn small" :disabled="busy||!!tenderRetry||!pricingTenderReady" @click="received=amount">{{ amount===totals.total?'Exact':money(amount,currency) }}</button></div><div class="ed-summary" style="font-size:15px;margin-top:25px"><span>Change to return</span><strong>{{ money(change,currency) }}</strong></div></template><template v-else><img v-if="method==='QR Pay'&&(company.qrCode||company.qrCodeUrl)" :src="company.qrCode||company.qrCodeUrl" alt="Store payment QR code" style="width:210px;max-height:210px;object-fit:contain;margin:0 auto 20px"><div class="ed-notice"><Icon name="card" /><div><strong>Confirm on your merchant device.</strong>MyFin records the payment. Your merchant app or card terminal confirms it.</div></div><label class="ed-actions" style="font-size:13px"><input v-model="confirmed" type="checkbox" :disabled="busy||!!tenderRetry||!pricingTenderReady">Payment confirmed on external device</label></template><section class="ed-editor-section"><h3>Email receipt (optional)</h3><p class="ed-muted">Save the email in your customer directory, then open the receipt in your mail app after payment.</p><div class="ed-form-grid"><label class="ed-field"><span>Customer name</span><input v-model="customerName" :disabled="busy||!!sourceRequest" maxlength="120" autocomplete="name"></label><label class="ed-field"><span>Customer email</span><input v-model.trim="customerEmail" :disabled="busy||!!sourceRequest" type="email" maxlength="254" autocomplete="email" inputmode="email" placeholder="customer@example.com"></label></div></section><div v-if="error" class="ed-alert" role="alert">{{ error }}</div><template #actions><button class="ed-btn" :disabled="busy||!!tenderRetry" @click="closePayment">Back to order</button><button class="ed-btn primary" :disabled="busy||(!tenderRetry&&!pricingTenderReady)" @click="complete"><Icon name="check" />{{ busy?'Saving payment…':tenderRetry?'Retry payment confirmation':!pricingTenderReady?(sourceRequest?'Reconnect first':'Refresh price first'):'Complete sale' }}</button></template></Modal>
<Modal v-if="modal==='success'" :title="lastSale.syncStatus==='pending'?'Saved on this device':lastSale.syncStatus==='review'?'Awaiting manager review':lastSale.syncStatus==='dismissed'?'Review resolved.':'A good sale.'" @close="modal=''"><div class="ed-success"><div class="ed-success-mark"><Icon name="check" /></div><h3>{{ lastSale.syncStatus==='pending'?'Payment recorded. Sync pending.':lastSale.syncStatus==='review'?'Payment secured on the server. Manager review pending.':lastSale.syncStatus==='dismissed'?'Payment review dismissed; no order was posted.':'Payment received. Order added to Sales Orders.' }}</h3><p class="ed-muted" style="font-size:11px;word-break:break-all;margin:10px 0 25px">{{ lastSale.number }}</p><div v-if="lastSale.syncStatus!=='dismissed'" class="ed-eyebrow">{{ lastSale.change?'CHANGE TO RETURN':'TOTAL COLLECTED' }}</div><strong v-if="lastSale.syncStatus!=='dismissed'">{{ money(lastSale.change||lastSale.total,currency) }}</strong></div><div v-if="lastSale.syncStatus==='pending'" class="ed-notice warning"><Icon name="cloud" /><div>Saved safely on this device. Do not take payment again. {{ needsReceiptReview(lastSale.syncError)?'The manager-review handoff is not confirmed yet. Retry sync when connected.':lastSale.syncError || 'This receipt will sync when your connection returns.' }}</div></div><div v-else-if="lastSale.syncStatus==='review'" class="ed-notice warning"><Icon name="cloud" /><div>The full payment record is secured on the server and is awaiting a manager or workspace owner. Do not collect payment again.</div></div><template #actions><button v-if="lastSale.syncStatus!=='dismissed'" class="ed-btn" @click="receipt=lastSale;modal=''"><Icon name="printer" />Receipt / Email</button><button class="ed-btn primary" @click="modal=''">New order<Icon name="arrow" /></button></template></Modal>
<Modal v-if="modal==='hold'" title="Keep this order for later." @close="modal=''"><label class="ed-field"><span>Order reference</span><input v-model="holdName" placeholder="Customer name or table" @keydown.enter="hold"></label><template #actions><button class="ed-btn" @click="modal=''">Cancel</button><button class="ed-btn primary" @click="hold">Hold order</button></template></Modal>
<Modal v-if="modal==='held'" title="Held carts on this device" @close="modal=''"><div v-for="(order,i) in held" :key="order.id" class="ed-row"><div><strong>{{ order.name }}</strong><small>{{ order.items.length }} lines · {{ money(order.total,currency) }}</small></div><button class="ed-btn small" @click="restore(i)">Restore</button></div><div v-if="!held.length" class="ed-empty"><Icon name="clock" /><h3>Nothing on hold.</h3><p>Hold a cart at checkout to pick it up later on this device.</p></div><p v-else class="ed-muted" style="margin-top:18px;font-size:12px">Restoring a cart parks your current cart automatically.</p></Modal>
<Modal v-if="modal==='recent'" title="Recent sales & receipts" wide @close="modal=''"><div v-for="sale in recent" :key="sale.id" class="ed-row"><div><strong style="font-size:11px">{{ sale.number }}</strong><small>{{ sale.customerName||'Walk-in customer' }} · {{ money(sale.total,currency) }}</small><span v-if="sale.syncStatus==='pending'" class="ed-pill warning">Awaiting sync</span><span v-else-if="sale.syncStatus==='review'" class="ed-pill warning">Awaiting manager review</span></div><button class="ed-btn small" @click="receipt=sale;modal=''"><Icon name="printer" />Receipt</button></div><p v-if="!recent.length" class="ed-muted">Completed sales will appear here.</p></Modal>
<Modal v-if="modal==='clear'" title="Start a fresh order?" @close="modal=''"><p class="ed-muted">{{ sourceRequest?'This removes the accepted request from this till. The request remains in Sales Orders and is not cancelled.':'Clear the items from this order, or hold it if the customer will return.' }}</p><template #actions><button class="ed-btn" @click="modal=''">Keep order</button><button class="ed-btn danger" @click="cart=[];discount=0;overrideReason='';voucherCode='';pricingQuote=null;saleId=newId();customerId='';customerEmail='';customerName='';sourceRequest=null;tenderRetry=null;modal=''">Clear order</button></template></Modal><Receipt v-if="receipt" :sale="receipt" @close="receipt=null" />
</div></template>
<style scoped>
.mf-pos-saving{color:var(--ed-success,#16734b);font-weight:700}.mf-pos-line-price{display:flex;align-items:center;gap:7px}.mf-pos-line-price s{color:var(--ed-muted);font-size:10px}.mf-pos-reward{align-items:center;background:color-mix(in srgb,var(--ed-success,#16734b) 7%,transparent);display:flex;justify-content:space-between;gap:12px}.mf-pos-reward>div{display:flex;flex-direction:column;gap:3px}.mf-pos-reward-label{color:var(--ed-success,#16734b);font-size:8px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.mf-pos-pricing-state{margin:8px 0;color:var(--ed-muted);font-size:10px}.mf-pos-pricing-state.error{color:var(--ed-danger,#a93226)}.mf-pos-offer>span:first-child{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.mf-pos-offer>span:first-child>small{width:100%;color:var(--ed-muted);font-size:8px}.mf-pos-offer em{border:1px solid var(--ed-line);padding:2px 5px;font-size:8px;font-style:normal;text-transform:uppercase;letter-spacing:.06em}.mf-pos-promotions{display:grid;gap:10px;margin-bottom:14px;padding:12px;border:1px solid var(--ed-line);background:var(--ed-wash)}.mf-pos-promotions>header{display:flex;align-items:center;justify-content:space-between;gap:10px}.mf-pos-promotions>header>div{display:grid;gap:4px}.mf-pos-code-input{display:flex;align-items:stretch;gap:7px}.mf-pos-code-input>input{flex:1;text-transform:uppercase}.mf-pos-code-input>.ed-icon-button{border:1px solid var(--ed-line);background:var(--ed-paper)}.mf-pos-discount-impact{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin:9px 0;background:var(--ed-line);border:1px solid var(--ed-line)}.mf-pos-discount-impact>div{display:grid;gap:4px;padding:9px;background:var(--ed-paper)}.mf-pos-discount-impact span{color:var(--ed-muted);font-size:8px;text-transform:uppercase;letter-spacing:.06em}.mf-pos-discount-impact strong{font-size:11px}.mf-pos-discount-impact>div:last-child strong{color:var(--ed-success,#16734b)}.mf-pos-promo-browser{display:grid;gap:20px}.mf-pos-promo-browser section{display:grid;gap:10px}.mf-pos-promo-browser h3{margin:0;font:500 20px var(--ed-font-sans)}.mf-pos-promo-list{display:grid;gap:7px}.mf-pos-promo-list article{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;border:1px solid var(--ed-line);padding:12px}.mf-pos-promo-list article.applied{border-color:var(--ed-success,#16734b);background:color-mix(in srgb,var(--ed-success,#16734b) 7%,transparent)}.mf-pos-promo-list article>span{display:grid;gap:4px}.mf-pos-promo-list small{color:var(--ed-muted);font-size:9px}.mf-pos-promo-list code{color:var(--ed-accent);font-weight:800;letter-spacing:.06em}.mf-pos-promo-list em{color:var(--ed-muted);font-size:9px;font-style:normal}@media(max-width:600px){.mf-pos-discount-impact{grid-template-columns:1fr}.mf-pos-promo-list article{grid-template-columns:auto 1fr}.mf-pos-promo-list :is(button,em){grid-column:2}.mf-pos-code-input{flex-wrap:wrap}.mf-pos-code-input>input{min-width:180px}}
</style>
